const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const val = change.value || {};
const messages = val.messages || [];

// If there are no messages, it is a delivery receipt (sent/delivered/read) - ignore
if (!messages || messages.length === 0) {
  return [];
}

const msg = messages[0];
const contact = (val.contacts && val.contacts[0]) || {};
const senderName = contact.profile ? contact.profile.name : 'Client';
const senderPhone = msg.from;
const messageText = msg.text ? msg.text.body : '';

if (!messageText || !senderPhone) {
  return [];
}

return [{
  json: {
    senderPhone,
    senderName,
    messageText,
    messageId: msg.id,
    timestamp: msg.timestamp,
    receivedAt: new Date().toISOString()
  }
}];

